#include <stdio.h>

int main() {
    int N;
    long long S;
    scanf("%d %lld", &N, &S);

    long long A[200000], B[200000], X[200000];
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld %lld", &A[i], &B[i], &X[i]);
    }

    long long current_time = 0;
    int count = 0;

    for (int i = 0; i < N; i++) {
        long long arrival = current_time + 1; // travel time
        if (arrival > S) break;

        long long wait = (A[i] * (arrival + X[i])) % B[i];
        long long leave_time = arrival + wait;

        if (leave_time > S) break;

        current_time = leave_time;
        count++;
    }

    printf("%d\n", count);
    return 0;
}

