int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n;
    scanf("%d", &n);
    int d[n];
    for (int i = 0; i < n; i++) scanf("%d", &d[i]);
    qsort(d, n, sizeof(int), cmp);

    int time = 0, count = 0;
