        time += 2; // 1 travel + 1 service
        if (time <= d[i]) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    ll *B = (ll *)malloc(sizeof(ll) * N);
    ll *C = (ll *)malloc(sizeof(ll) * N);
    ll *D = (ll *)malloc(sizeof(ll) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld %lld %lld", &A[i], &B[i], &C[i], &D[i]);
    }

    /*
      dp[i] = earliest time after finishing shopping at store i
      if we shop at stores 0..i in order and can reach i before it closes.

      Transition:
      Arrive at store i at time dp[i-1] + 1 (or 1 for first store).
      Need to wait until time t satisfying:
          t >= arrival
          t % A[i] == B[i]
      Then shopping itself takes C[i] time, and must finish by D[i].

      Earliest such t:
          if arrival <= B mod A adjusted upward:
              t = smallest >= arrival with t % A == B
          formula:
              rem = arrival % A
              need = (B - rem + A) % A
              t = arrival + need

      finish = t + C
      feasible if finish <= D
    */

    ll cur_finish = 0;
    int ans = 0;

    for (int i = 0; i < N; i++) {
        ll arrival = (i == 0 ? 1 : cur_finish + 1);

        ll rem = arrival % A[i];
        ll need = (B[i] - rem + A[i]) % A[i];
        ll start = arrival + need;
        ll finish = start + C[i];

        if (finish > D[i]) break;

        cur_finish = finish;
        ans++;
    }

    printf("%d\n", ans);

    free(A);
    free(B);
    free(C);
    free(D);
    return 0;
}

