using namespace std;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    struct Store {
        int64 A, B, C, D;
    };
    vector<Store> stores(N);
    for (int i = 0; i < N; i++) {
        cin >> stores[i].A >> stores[i].B >> stores[i].C >> stores[i].D;
    }

    // Sort by opening time
    sort(stores.begin(), stores.end(), [](const Store& a, const Store& b) {
        return a.A < b.A;
    });

    // Min-heap: stores by closing time (B)
    priority_queue<pair<int64, int>, vector<pair<int64, int>>, greater<>> pq;
    int idx = 0;
    int64 t = 0;
    int ans = 0;

    while (true) {
        // Add all stores that have opened by time t
        while (idx < N && stores[idx].A <= t) {
            pq.push({stores[idx].B, idx});
            idx++;
        }
        // Remove stores that are already closed
        while (!pq.empty() && pq.top().first < t) {
            pq.pop();
        }
        if (pq.empty()) {
            // No store available now, jump to next opening time
            if (idx < N) {
                t = stores[idx].A;
                continue;
            } else {
                break;
            }
        }
        // Pick store that closes earliest
        auto [closeTime, storeIdx] = pq.top();
        pq.pop();
        int64 wait = stores[storeIdx].C * t + stores[storeIdx].D;
        int64 finishTime = t + wait + 1; // +1 for travel to next
        if (finishTime - 1 <= closeTime) { // can finish before store closes
            ans++;
            t = finishTime;
        } else {
            // Can't make it, skip this store
            continue;
        }
    }

    cout << ans << "\n";
    return 0;
}

