#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int64> T(N), A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> T[i] >> A[i] >> B[i];

    // dp[k] = minimum time when Takahashi is back at home
    // after shopping exactly k times.
    const int64 INF = (1LL << 62);
    vector<int64> dp(N + 1, INF);
    dp[0] = 0;

    for (int i = 0; i < N; ++i) {
        vector<int64> ndp = dp;

        for (int k = 0; k < N; ++k) {
            if (dp[k] == INF) continue;

            // Leave home at time dp[k], arrive at store at time x
            int64 x = dp[k] + 1;

            // Waiting time is (A[i] * x + B[i]) mod T[i]
            int64 wait = (A[i] * x + B[i]) % T[i];

            // Need to finish shopping before store closes at time T[i]
            // Total time spent at store is wait, then 1 unit to return home.
            // So back home at:
            int64 back = x + wait + 1;

            if (back <= T[i]) {
                ndp[k + 1] = min(ndp[k + 1], back);
            }
        }

        dp.swap(ndp);
    }

    int ans = 0;
    for (int k = N; k >= 0; --k) {
        if (dp[k] != INF) {
            ans = k;
            break;
        }
    }

    cout << ans << '\n';
    return 0;
}

