            P[i] = Long.parseLong(parts[1]);
            C[i] = Long.parseLong(parts[2]);
        }

        long currentTime = 0;
        int trips = 0;

        outer:
        while (true) {
            // start a new trip from home
            long t = 0; // time at start of this trip (home)
            for (int i = 0; i < N; i++) {
                t += 1; // travel to store i (1 unit)
                if (t >= C[i]) {
                    break outer; // store already closed
                }
                long wait = A[i] / (t + P[i]);
                t += wait;
                // after shopping, we move to next store or home
                // but check if store is closing condition already passed
                // Note: condition says arrival time must be < C[i]; we already checked before wait
            }
            // after finishing store N, return home (instant)
            trips++;
            currentTime = t; // not strictly needed for simulation but could be used
        }

        System.out.println(trips);
    }
}

