import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long T = fs.nextLong();

        long[] A = new long[N];
        long[] B = new long[N];

        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            B[i] = fs.nextLong();
        }

        // dp[k] = minimum time after finishing exactly k shopping trips
        // Initialize with INF
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[N + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < N; i++) {
            long[] ndp = Arrays.copyOf(dp, N + 1);

            for (int k = 0; k < i + 1; k++) {
                if (dp[k] == INF) continue;

                // Move to store i: +1 time
                long arrive = dp[k] + 1;
                if (arrive > T) continue;

                // Waiting time formula:
                // if arrive time is x, total finish time at this store is:
                // x + A[i] * x + B[i]
                // = (A[i] + 1) * x + B[i]
                long finish;
                if (A[i] > 0 && arrive > (INF - B[i]) / (A[i] + 1)) {
                    finish = INF;
                } else {
                    finish = (A[i] + 1) * arrive + B[i];
                }

                if (finish <= T) {
                    ndp[k + 1] = Math.min(ndp[k + 1], finish);
                }
            }

            dp = ndp;
        }

        int ans = 0;
        for (int k = N; k >= 0; k--) {
            if (dp[k] <= T) {
                ans = k;
                break;
            }
        }

        System.out.println(ans);
    }
}
